// ai-agents/harness/src/routines/upgrades.ts: sketch: one small pipeline per package (FE and BE upgrade fixers).
// Runs in the harness inside the VM: `vm` is this VM's checkout, commands and agent sessions.
export async function repairGroup(vm: Vm, pr: RenovatePr, charter: Charter): Promise<RepairResult> {
  const breaking: Bump[] = [];
  for (const bump of pr.bumps) {  // 1. each bump alone on the base commit
    await vm.checkout(pr.baseSha);
    await vm.applyBump(bump);  // npm: package.json + lockfile; uv: uv lock --upgrade-package
    if (!(await vm.run(charter.verify_cmd))) breaking.push(bump);  // npm run verify / poe verify (G7)
  }
  const fixCommits: string[] = [];
  for (const bump of breaking) {  // 2. one fix session per breaking package, one writer
    await vm.checkout(pr.baseSha);
    await vm.applyBump(bump);
    const result = await vm.session({ task: "upgrade-dependency", package: bump.package, to: bump.newVersion,
                                      context: [bump.changelogUrl, await vm.usages(bump.package)],
                                      effort: "low", retryEffort: "medium" });
    if (!result.green) {
      return RepairResult.handOff(bump, result.notes);  // a PR comment explains; a person decides
    }
    fixCommits.push(...result.commits);
  }

  await vm.checkout(pr.headSha);  // 3. all fixes together on the real Renovate branch
  await vm.cherryPick(fixCommits);
  if (!(await vm.run([charter.verify_cmd, ...charter.flow_checks]))) {  // flows and stories that use each package
    return RepairResult.handOff(undefined, "the fixes pass one by one but not together");
  }
  return RepairResult.push({ branch: pr.headBranch });  // the broker's git proxy allows this branch only
}
